import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const c=JSON.parse('{"title":"Felder anlegen und ändern","description":"Felder eines Grids anlegen, umbenennen, im Typ ändern und löschen.","frontmatter":{"title":"Felder anlegen und ändern","description":"Felder eines Grids anlegen, umbenennen, im Typ ändern und löschen."},"headers":[],"relativePath":"grids/felder.md","filePath":"grids/felder.md","lastUpdated":1786357627000}'),a={name:"grids/felder.md"};function l(s,e,d,o,h,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="felder-anlegen-und-andern" tabindex="-1">Felder anlegen und ändern <a class="header-anchor" href="#felder-anlegen-und-andern" aria-label="Permalink to &quot;Felder anlegen und ändern&quot;">​</a></h1><p>Ein <strong>Feld</strong> ist eine Spalte eines Grids. Anders als Filter oder Sortierung gelten Felder für das <strong>ganze Grid</strong> — Änderungen wirken in allen Ansichten, Formularen und Flows.</p><h2 id="feld-anlegen" tabindex="-1">Feld anlegen <a class="header-anchor" href="#feld-anlegen" aria-label="Permalink to &quot;Feld anlegen&quot;">​</a></h2><ol><li>Klicken Sie am rechten Ende der Spaltenköpfe auf <strong>+</strong>.</li><li>Vergeben Sie einen <strong>Spaltenname</strong>.</li><li>Wählen Sie den <strong>Spaltentyp</strong>.</li><li>Konfigurieren Sie den Typ, falls er Einstellungen hat.</li></ol><p>Der Vorschlagsname lautet <em>Neues Feld</em>.</p><p>→ <a href="/referenz/spaltentypen">Spaltentypen-Referenz</a></p><h2 id="typen-mit-einstellungen" tabindex="-1">Typen mit Einstellungen <a class="header-anchor" href="#typen-mit-einstellungen" aria-label="Permalink to &quot;Typen mit Einstellungen&quot;">​</a></h2><p>Nicht jeder Typ ist sofort fertig konfiguriert:</p><table tabindex="0"><thead><tr><th>Typ</th><th>Einstellung</th></tr></thead><tbody><tr><td><strong>Einzelauswahl</strong>, <strong>Mehrfachauswahl</strong></td><td><em>Auswahl Einstellungen</em> — Optionsliste, <em>Andere Optionen zulassen</em></td></tr><tr><td><strong>Währung</strong></td><td><em>Wählen Sie eine Währung</em>, dazu Dezimalstellen</td></tr><tr><td><strong>Eintrag verknüpfen</strong>, <strong>Mehrere Einträge verknüpfen</strong></td><td><em>Wählen Sie die Ansicht aus der Zeilen verknüpft werden können</em></td></tr><tr><td><strong>Interne Verknüpfung</strong></td><td><em>Wählen Sie einen oder mehrere Ressourcentypen (optional)</em></td></tr><tr><td><strong>Wert übernehmen</strong>, <strong>Summe berechnen</strong></td><td>Verknüpfungsfeld und Zielfeld</td></tr><tr><td><strong>Formel</strong></td><td>Ausdruck und Ergebnistyp</td></tr></tbody></table><h3 id="auswahloptionen" tabindex="-1">Auswahloptionen <a class="header-anchor" href="#auswahloptionen" aria-label="Permalink to &quot;Auswahloptionen&quot;">​</a></h3><p>Im Dialog <em>Auswahl Einstellungen</em> legen Sie die Optionen an. Über <em>Eine Option finden</em> durchsuchen Sie längere Listen.</p><p><strong>Andere Optionen zulassen</strong> erlaubt zusätzlich Freitext — im Formular erscheint dann <em>Sonstige Eingabe</em>.</p><div class="tip custom-block"><p class="custom-block-title">Optionsreihenfolge wirkt weiter</p><p>Die Reihenfolge der Optionen bestimmt die Spaltenreihenfolge im <a href="/ansichten/kanban">Kanban-Board</a> und die Reihenfolge im Formular. Legen Sie sie also bewusst fest — etwa entlang des Prozesses statt alphabetisch.</p></div><p>Fehlermeldungen: <em>Die Option darf nicht leer sein</em>, <em>Die Option darf kein Duplikat sein</em>.</p><h2 id="feld-bearbeiten" tabindex="-1">Feld bearbeiten <a class="header-anchor" href="#feld-bearbeiten" aria-label="Permalink to &quot;Feld bearbeiten&quot;">​</a></h2><p>Über das Menü im Spaltenkopf:</p><table tabindex="0"><thead><tr><th>Aktion</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Feld bearbeiten</strong></td><td>Öffnet Spaltenname und Spaltentyp</td></tr><tr><td><strong>Spaltenbeschreibung bearbeiten</strong></td><td>Erklärender Text zum Feld</td></tr><tr><td><strong>Feldkey verwalten</strong></td><td>Technischer Bezeichner</td></tr></tbody></table><h3 id="umbenennen" tabindex="-1">Umbenennen <a class="header-anchor" href="#umbenennen" aria-label="Permalink to &quot;Umbenennen&quot;">​</a></h3><p>Unkritisch: Ansichten, Formulare und Flows verweisen intern nicht über den Namen und funktionieren weiter.</p><p>Fehlermeldung bei Dopplung: <em>Der Name existiert bereits</em>. Bei zu langen Namen: <em>Der Name kann maximal {max} Zeichen lang sein.</em></p><h3 id="beschreibung" tabindex="-1">Beschreibung <a class="header-anchor" href="#beschreibung" aria-label="Permalink to &quot;Beschreibung&quot;">​</a></h3><p>Die Spaltenbeschreibung erscheint auch in <a href="/formulare/felder-konfigurieren">Formularen</a> als Hilfetext unter dem Feld.</p><div class="tip custom-block"><p class="custom-block-title">Ein Satz spart viele Rückfragen</p><p>Gerade bei Feldern, die andere Menschen ausfüllen, senkt eine kurze Erklärung die Fehlerquote deutlich — „Bitte mit Ländervorwahl, z. B. +49…&quot;.</p></div><h3 id="feldkey" tabindex="-1">Feldkey <a class="header-anchor" href="#feldkey" aria-label="Permalink to &quot;Feldkey&quot;">​</a></h3><p>Ein <strong>Key</strong> ist ein zusätzlicher, lesbarer Bezeichner eines Feldes — unabhängig von seinem Namen. Die Oberfläche erklärt ihn als <em>lesbaren Identifier einer Spalte</em>, der verwendet wird, <em>um ein Grid mit einer App zu verbinden</em>.</p><p>Gebraucht wird er dort, wo etwas außerhalb des Grids ein bestimmtes Feld ansprechen muss, ohne sich auf den Namen zu verlassen: in der Programmierschnittstelle, in Formularwerten — und in <a href="/apptiveteams/team-space">ApptiveTeams</a>, wo die App ihre gesamte Konfiguration über Keys findet.</p><p>Alle Keys eines Grids auf einmal vergeben Sie über <strong>Felder Keys verwalten</strong> im Menü (⋮) der Ansicht.</p><div class="tip custom-block"><p class="custom-block-title">Namen sind für Menschen, Keys für Systeme</p><p>Weil Name und Key getrennt sind, können Sie eine Spalte jederzeit umbenennen, ohne eine angebundene App oder Schnittstelle zu brechen. Vergeben Sie Keys deshalb bewusst und ändern Sie sie danach nicht mehr.</p></div><h3 id="typ-andern" tabindex="-1">Typ ändern <a class="header-anchor" href="#typ-andern" aria-label="Permalink to &quot;Typ ändern&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Typänderung kann Werte verlieren</p><p>ApptiveGrid versucht, vorhandene Werte zu übernehmen. Passt ein Wert nicht zum neuen Typ, geht er verloren — ohne Nachfrage je Zeile.</p><p>Ziehen Sie bei gefüllten Spalten vorher einen <a href="/grids/csv-export">CSV-Export</a> als Sicherung.</p></div><p>Typische Fälle:</p><table tabindex="0"><thead><tr><th>Änderung</th><th>Ergebnis</th></tr></thead><tbody><tr><td>Text → Zahl</td><td>Nicht-numerische Werte gehen verloren</td></tr><tr><td>Text → Einzelauswahl</td><td>Werte ohne passende Option gehen verloren</td></tr><tr><td>Zahl → Text</td><td>Unkritisch</td></tr><tr><td>Datum → Text</td><td>Unkritisch, aber Datumsfilter entfallen</td></tr><tr><td>Beliebig → Verknüpfung</td><td>Werte gehen in aller Regel verloren</td></tr></tbody></table><p>Blockiert ein Filter die Änderung, meldet ApptiveGrid:</p><blockquote><p><em>Änderung nicht möglich. Dieses Feld wird in einem Filter verwendet.</em></p></blockquote><p>Entfernen Sie den Filter — er kann in <strong>jeder</strong> Ansicht des Grids liegen, nicht nur in der geöffneten.</p><h2 id="feldkey-1" tabindex="-1">Feldkey <a class="header-anchor" href="#feldkey-1" aria-label="Permalink to &quot;Feldkey&quot;">​</a></h2><p>Der <strong>Feldkey</strong> ist der technische Bezeichner eines Feldes. Er ist relevant, wenn Sie über die <a href="/integrationen/api-zugangsdaten">Programmierschnittstelle</a> auf das Grid zugreifen.</p><p>Für die Arbeit in der Oberfläche brauchen Sie ihn nicht.</p><h2 id="feld-loschen" tabindex="-1">Feld löschen <a class="header-anchor" href="#feld-loschen" aria-label="Permalink to &quot;Feld löschen&quot;">​</a></h2><p>Über das Spaltenmenü, mit Bestätigung.</p><div class="danger custom-block"><p class="custom-block-title">Löschen entfernt die Werte aus allen Einträgen</p><p>Das lässt sich nicht rückgängig machen. Prüfen Sie vorher, ob das Feld verwendet wird:</p><ul><li>in <strong>Filtern, Sortierungen, Gruppierungen</strong> einer Ansicht</li><li>in <strong>Formularen</strong></li><li>in <strong>Flows</strong> — als Auslöserbedingung oder in einer Aktion</li><li>in <strong>berechneten Feldern</strong> — als Zielfeld einer Übernahme oder Summe</li><li>in <strong>Seiten</strong> — als Eingabefeld oder in einer bedingten Sichtbarkeit</li></ul></div><h2 id="feld-ausblenden-statt-loschen" tabindex="-1">Feld ausblenden statt löschen <a class="header-anchor" href="#feld-ausblenden-statt-loschen" aria-label="Permalink to &quot;Feld ausblenden statt löschen&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Die sicherere Alternative</p><p>Wird ein Feld nicht mehr gebraucht, aber die alten Werte sollen erhalten bleiben, blenden Sie es in allen Ansichten aus, statt es zu löschen. Die Daten bleiben verfügbar, die Tabelle wird trotzdem übersichtlich.</p><p>→ <a href="/ansichten/spalten-verwalten">Spalten verwalten</a></p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/referenz/spaltentypen">Spaltentypen-Referenz</a></li><li><a href="/grids/verknuepfungen">Grids verknüpfen</a></li><li><a href="/grids/berechnete-felder">Berechnete Felder</a></li></ul>',45)])])}const g=n(a,[["render",l]]);export{c as __pageData,g as default};
